def build():
    out = []
    for m, items in QUIZ.items():
        for i, (q, opts, ex) in enumerate(items):
            out.append({'id': '%s-p%d' % (m, i + 1), 'm': m, 'q': esc(q), 'o': [esc(o) for o in opts], 'a': 0,
                        'e': ex.inline(), 'src': [ex.ref]})
    return push_js('quiz', out)
